"""FENIX CPU controller: wire validation and certified epoch planning.

The classifier modules, probability compiler and metric routines are supplied
CPU components.  This module performs strict request validation and drives the
planner (see planner.py) for every epoch of the batch.
"""
import json

MAX_INPUT = 16 * 1024 * 1024


class Invalid(Exception):
    pass


def _no_dup(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise Invalid('duplicate key')
        d[k] = v
    return d


def _bad_const(_):
    raise Invalid('nonfinite')


def _bad_float(_):
    raise Invalid('noninteger number')


def _need_int(v, lo, hi):
    if type(v) is not int or v < lo or v > hi:
        raise Invalid('integer out of range')
    return v


CASE_KEYS = frozenset((
    'model', 'class_values', 'stats', 'bucket', 'slots', 'flows', 'groups',
    'windows'))


def parse_request(raw):
    if type(raw) is not bytes:
        raise Invalid('input type')
    if len(raw) > MAX_INPUT:
        raise Invalid('input size')
    try:
        text = raw.decode('utf-8')
    except Exception:
        raise Invalid('utf-8')
    try:
        return json.loads(text, object_pairs_hook=_no_dup,
                          parse_constant=_bad_const, parse_float=_bad_float)
    except Invalid:
        raise
    except Exception:
        raise Invalid('json')


def _validate_case(case):
    if type(case) is not dict or len(case) != 8:
        raise Invalid('case keys')
    if set(case.keys()) != CASE_KEYS:
        raise Invalid('case keys')

    if case['model'] != 'cnn' and case['model'] != 'rnn':
        raise Invalid('model')

    cv = case['class_values']
    if type(cv) is not list or len(cv) != 7:
        raise Invalid('class_values')
    for v in cv:
        _need_int(v, 1, 1000)

    st = case['stats']
    if type(st) is not list or len(st) != 3:
        raise Invalid('stats')
    for v in st:
        _need_int(v, 1, 10 ** 9)

    bk = case['bucket']
    if type(bk) is not list or len(bk) != 2:
        raise Invalid('bucket')
    bucket_cap = _need_int(bk[0], 1, 512)
    _need_int(bk[1], 0, bucket_cap)

    sl = case['slots']
    if type(sl) is not list or len(sl) < 1 or len(sl) > 256:
        raise Invalid('slots')
    prev = -1
    for row in sl:
        if type(row) is not list or len(row) != 3:
            raise Invalid('slot row')
        t = _need_int(row[0], 0, 10 ** 12)
        if t <= prev:
            raise Invalid('slot times')
        prev = t
        _need_int(row[1], 0, 512)
        _need_int(row[2], 0, 512)
    if sl[0][2] != 0:
        raise Invalid('first refill')

    gr = case['groups']
    if type(gr) is not list or len(gr) > 32:
        raise Invalid('groups')
    ngroups = len(gr)
    for row in gr:
        if type(row) is not list or len(row) != 2:
            raise Invalid('group row')
        p = row[0]
        if type(p) is not int or not (p == -1 or 0 <= p < ngroups):
            raise Invalid('group parent')
        _need_int(row[1], 0, 512)
    for idx in range(ngroups):
        cur = gr[idx][0]
        steps = 0
        while cur != -1:
            steps += 1
            if steps > ngroups:
                raise Invalid('group cycle')
            cur = gr[cur][0]

    fl = case['flows']
    if type(fl) is not list or len(fl) < 1 or len(fl) > 32:
        raise Invalid('flows')
    for row in fl:
        if type(row) is not list or len(row) != 4:
            raise Invalid('flow row')
        tgt = _need_int(row[0], 1, 64)
        _need_int(row[1], tgt, 512)
        gp = row[2]
        if type(gp) is not int or not (gp == -1 or 0 <= gp < ngroups):
            raise Invalid('flow group')
        _need_int(row[3], 0, 6)

    wd = case['windows']
    if type(wd) is not list or len(wd) > 512:
        raise Invalid('windows')
    nflows = len(fl)
    for row in wd:
        if type(row) is not list or len(row) != 8:
            raise Invalid('window row')
        _need_int(row[0], 0, nflows - 1)
        ready = _need_int(row[1], 0, 10 ** 12)
        expires = _need_int(row[2], 0, 10 ** 12)
        if expires < ready:
            raise Invalid('window expiry')
        _need_int(row[3], 1, 65535)
        _need_int(row[4], 1, 320)
        _need_int(row[5], 0, 65535)
        _need_int(row[6], 1, 1000)
        feats = row[7]
        if type(feats) is not list or len(feats) != 9:
            raise Invalid('features')
        for frow in feats:
            if type(frow) is not list or len(frow) != 2:
                raise Invalid('feature row')
            _need_int(frow[0], 0, 1500)
            _need_int(frow[1], 0, 2560)
    return len(wd)


def validate(obj):
    if type(obj) is not dict or len(obj) != 2:
        raise Invalid('top keys')
    if 'version' not in obj or 'cases' not in obj:
        raise Invalid('top keys')
    version = obj['version']
    if type(version) is not int or version != 3:
        raise Invalid('version')
    cases = obj['cases']
    if type(cases) is not list or len(cases) > 8:
        raise Invalid('cases')
    total = 0
    for case in cases:
        total += _validate_case(case)
    if total > 1024:
        raise Invalid('window budget')
    return cases


def run(raw):
    """Validate the whole request, then plan every epoch in order."""
    cases = validate(parse_request(raw))
    import planner
    results = []
    for case in cases:
        results.append(planner.solve_epoch(case))
    return {'version': 3, 'results': results}
